 parts=format(x.log);
 const pct=s.target>0?Math.floor((x.q/s.target)*1000)/10:100;
 const actionLabel=s.cosmicAction==='steady'?'専用ステディハンド':s.cosmicAction==='miracle'?'ミラクルマテリアル':'なし';
 const miracle=s.cosmicAction==='miracle'?'<br><span class="error">ミラクルマテリアルのランダムな有利状態は保証値へ加算していません。</span>':'';
