 $('summary').innerHTML=`<div class="summary"><strong>最大品質には届きませんでした。</strong><br>${s.label}<br>専用アクション: ${actionLabel}<br>${x.log.length}アクション / ${parts.length}マクロ / 約${seconds}秒　到達: 工数 ${x.p}/${s.diff}・品質 <strong>${x.q}/${s.target}（${pct}%）</strong>・残CP ${x.cp}・残耐久 ${x.d}<br>検算値: 基礎工数 ${base.p}・基礎品質 ${base.q}<br><span class="skill-note">現在の広域探索で、完成できた候補の中から確認できた最高品質です。理論上の絶対最大値を保証する表示ではありません。</span>${miracle}${warning}</div>`;
 $('result').textContent=parts.map((p,i)=>`--- BEST EFFORT MACRO ${i+1} ---\n${p}`).join('\n\n');
